  1→/**
  2→ * Prompt execution engine combining Nunjucks templating with AI/Core
  3→ */
  4→
  5→import nunjucks from 'nunjucks';
  6→import { BaseLLM, ChatParams, ChatResult } from '@memberjunction/ai';
  7→import { PromptFileLoader } from './PromptFileLoader.js';
  8→import { AIConfig } from '../types/config.js';
  9→import { PromptExecutionResult } from '../types/prompts.js';
 10→import { createLLMInstance } from '../utils/llm-factory.js';
 11→import { CleanAndParseJSON } from '@memberjunction/global';
 12→
 13→export type GuardrailCheckFn = () => { canContinue: boolean; reason?: string };
 14→
 15→export class PromptEngine {
 16→  private nunjucksEnv: nunjucks.Environment;
 17→  private llm: BaseLLM;
 18→  private guardrailCheck?: GuardrailCheckFn;
 19→
 20→  constructor(
 21→    private config: AIConfig,
 22→    promptsDir: string
 23→  ) {
 24→    // Initialize Nunjucks with custom loader
 25→    const loader = new PromptFileLoader(promptsDir);
 26→    this.nunjucksEnv = new nunjucks.Environment(loader, {
 27→      autoescape: false,
 28→      dev: true
 29→    });
 30→
 31→    // Add custom filters
 32→    this.addCustomFilters();
 33→
 34→    // Initialize AI/Core LLM
 35→    this.llm = this.createLLM();
 36→  }
 37→
 38→  /**
 39→   * Set guardrail checking callback
 40→   * This will be called before every LLM execution to check if we should continue
 41→   */
 42→  public setGuardrailCheck(checkFn: GuardrailCheckFn): void {
 43→    this.guardrailCheck = checkFn;
 44→  }
 45→
 46→  /**
 47→   * Initialize the prompt loader
 48→   */
 49→  public async initialize(): Promise<void> {
 50→    const env = this.nunjucksEnv as { loaders?: PromptFileLoader[] };
 51→    const loader = env.loaders?.[0];
 52→    if (loader) {
 53→      await loader.loadAll();
 54→    }
 55→  }
 56→
 57→  /**
 58→   * Create appropriate LLM based on provider configuration
 59→   * Uses MJ ClassFactory pattern for BaseLLM instantiation
 60→   */
 61→  private createLLM(): BaseLLM {
 62→    // Use shared factory (DRY principle)
 63→    return createLLMInstance(this.config.provider, this.config.apiKey);
 64→  }
 65→
 66→  /**
 67→   * Add custom Nunjucks filters
 68→   * Pattern from Templates package
 69→   */
 70→  private addCustomFilters(): void {
 71→    // JSON formatting with indentation
 72→    this.nunjucksEnv.addFilter('json', (obj: any, indent: number = 2) => {
 73→      try {
 74→        return JSON.stringify(obj, null, indent);
 75→      } catch (error) {
 76→        return `[Error serializing to JSON: ${(error as Error).message}]`;
 77→      }
 78→    });
 79→
 80→    // Compact JSON
 81→    this.nunjucksEnv.addFilter('jsoninline', (obj: any) => {
 82→      try {
 83→        return JSON.stringify(obj);
 84→      } catch (error) {
 85→        return `[Error serializing to JSON: ${(error as Error).message}]`;
 86→      }
 87→    });
 88→
 89→    // Parse JSON strings
 90→    this.nunjucksEnv.addFilter('jsonparse', (str: string) => {
 91→      try {
 92→        return JSON.parse(str);
 93→      } catch (error) {
 94→        return str;
 95→      }
 96→    });
 97→
 98→    // Array join filter
 99→    this.nunjucksEnv.addFilter('join', (arr: any[], separator: string = ', ') => {
100→      return Array.isArray(arr) ? arr.join(separator) : arr;
101→    });
102→  }
103→
104→  /**
105→   * Render a Nunjucks template with context
106→   * Pattern from Templates.renderTemplateAsync()
107→   */
108→  private async renderTemplate(promptName: string, context: any): Promise<string> {
109→    return new Promise((resolve, reject) => {
110→      this.nunjucksEnv.render(promptName, context, (err, result) => {
111→        if (err) {
112→          console.error(`[PromptEngine] FATAL: Template rendering failed for ${promptName}`);
113→          console.error(`[PromptEngine] Error:`, err.message);
114→          console.error(`[PromptEngine] Context keys:`, Object.keys(context));
115→          console.error(`[PromptEngine] Terminating process due to template rendering failure`);
116→          process.exit(1);
117→        }
118→        resolve(result || '');
119→      });
120→    });
121→  }
122→
123→  /**
124→   * Execute a prompt with AI/Core
125→   * Main entry point for DBAutoDoc analysis
126→   */
127→  public async executePrompt<T>(
128→    promptName: string,
129→    context: any,
130→    options?: {
131→      systemPrompt?: string;
132→      temperature?: number;
133→      maxTokens?: number;
134→      responseFormat?: 'JSON' | 'Text';
135→    }
136→  ): Promise<PromptExecutionResult<T>> {
137→    try {
138→      // Check guardrails before executing
139→      if (this.guardrailCheck) {
140→        const check = this.guardrailCheck();
141→        if (!check.canContinue) {
142→          return {
143→            success: false,
144→            errorMessage: `Guardrail limit exceeded: ${check.reason}`,
145→            tokensUsed: 0,
146→            guardrailExceeded: true
147→          };
148→        }
149→      }
150→
151→      // 1. Render Nunjucks template with context
152→      const renderedPrompt = await this.renderTemplate(promptName, context);
153→
154→      // 2. Build ChatParams for AI/Core
155→      const messages = [];
156→
157→      // Add system prompt if provided
158→      if (options?.systemPrompt) {
159→        messages.push({
160→          role: 'system' as const,
161→          content: options.systemPrompt
162→        });
163→      }
164→
165→      // Add rendered user prompt
166→      messages.push({
167→        role: 'user' as const,
168→        content: renderedPrompt
169→      });
170→
171→      const params: ChatParams = {
172→        model: this.config.model,
173→        messages,
174→        maxOutputTokens: options?.maxTokens ?? this.config.maxTokens,
175→        responseFormat: options?.responseFormat ?? 'JSON',
176→        ...(options?.temperature != null && { temperature: options.temperature }),
177→        ...(this.config.temperature != null && options?.temperature == null && { temperature: this.config.temperature }),
178→        ...(this.config.effortLevel != null && { effortLevel: this.config.effortLevel.toString() }) // Optional 1-100, BaseLLM drivers handle if supported
179→      };
180→
181→      // 3. Execute with AI/Core (follows RunView pattern - doesn't throw)
182→      const chatResult: ChatResult = await this.llm.ChatCompletion(params);
183→
184→      // 4. Check success (IMPORTANT: like RunView, check .success property)
185→      if (!chatResult.success) {
186→        return {
187→          success: false,
188→          errorMessage: chatResult.errorMessage || 'Unknown error',
189→          tokensUsed: 0
190→        };
191→      }
192→
193→      // 5. Extract result and parse JSON if needed
194→      const content = chatResult.data.choices[0].message.content;
195→      const usage = chatResult.data.usage;
196→
197→      let parsedResult: T;
198→      if (options?.responseFormat === 'JSON') {
199→        // Use shared MJGlobal utility for JSON cleaning (handles markdown fences, double-escaping, etc.)
200→        const parsed = CleanAndParseJSON<T>(content, true);
201→        if (parsed === null) {
202→          return {
203→            success: false,
204→            errorMessage: `Failed to parse JSON response\n\nRaw content:\n${content}`,
205→            tokensUsed: usage?.totalTokens || 0,
206→            promptInput: renderedPrompt,
207→            promptOutput: content
208→          };
209→        }
210→        parsedResult = parsed;
211→      } else {
212→        parsedResult = content as unknown as T;
213→      }
214→
215→      return {
216→        success: true,
217→        result: parsedResult,
218→        tokensUsed: usage?.totalTokens || 0,
219→        cost: usage?.cost,
220→        promptInput: renderedPrompt,
221→        promptOutput: content
222→      };
223→
224→    } catch (error) {
225→      return {
226→        success: false,
227→        errorMessage: `Prompt execution failed: ${(error as Error).message}`,
228→        tokensUsed: 0
229→      };
230→    }
231→  }
232→
233→  /**
234→   * Execute multiple prompts in parallel
235→   * Uses AI/Core's ChatCompletions for efficiency
236→   */
237→  public async executePromptsParallel<T>(
238→    requests: Array<{
239→      promptName: string;
240→      context: any;
241→      options?: {
242→        systemPrompt?: string;
243→        temperature?: number;
244→        maxTokens?: number;
245→        responseFormat?: 'JSON' | 'Text';
246→      };
247→    }>
248→  ): Promise<Array<PromptExecutionResult<T>>> {
249→    try {
250→      // Render all templates first
251→      const renderedPrompts = await Promise.all(
252→        requests.map(req => this.renderTemplate(req.promptName, req.context))
253→      );
254→
255→      // Build ChatParams array
256→      const paramsArray: ChatParams[] = renderedPrompts.map((prompt, i) => {
257→        const params: ChatParams = {
258→          model: this.config.model,
259→          messages: [{ role: 'user', content: prompt }],
260→          maxOutputTokens: requests[i].options?.maxTokens ?? this.config.maxTokens,
261→          responseFormat: requests[i].options?.responseFormat ?? 'JSON'
262→        };
263→
264→        // Only add temperature if explicitly provided (don't default to 0.1)
265→        if (requests[i].options?.temperature != null) {
266→          params.temperature = requests[i].options!.temperature;
267→        } else if (this.config.temperature != null) {
268→          params.temperature = this.config.temperature;
269→        }
270→
271→        return params;
272→      });
273→
274→      // Execute in parallel using AI/Core
275→      const results = await this.llm.ChatCompletions(paramsArray);
276→
277→      // Parse and return
278→      return results.map((chatResult, i) => {
279→        if (!chatResult.success) {
280→          return {
281→            success: false,
282→            errorMessage: chatResult.errorMessage,
283→            tokensUsed: 0
284→          };
285→        }
286→
287→        const content = chatResult.data.choices[0].message.content;
288→        const usage = chatResult.data.usage;
289→
290→        // Use shared MJGlobal utility for JSON cleaning (handles markdown fences, double-escaping, etc.)
291→        const parsed = CleanAndParseJSON<T>(content, true);
292→        if (parsed === null) {
293→          return {
294→            success: false,
295→            errorMessage: `JSON parse error`,
296→            tokensUsed: usage?.totalTokens || 0
297→          };
298→        }
299→        return {
300→          success: true,
301→          result: parsed,
302→          tokensUsed: usage?.totalTokens || 0,
303→          cost: usage?.cost
304→        };
305→      });
306→    } catch (error) {
307→      // If rendering or execution fails completely, return array of errors
308→      return requests.map(() => ({
309→        success: false,
310→        errorMessage: `Parallel execution failed: ${(error as Error).message}`,
311→        tokensUsed: 0
312→      }));
313→    }
314→  }
315→}
