  1→/**
  2→ * Manages granular guardrails enforcement for DBAutoDoc analysis
  3→ *
  4→ * Supports:
  5→ * - Per-phase token limits (discovery, analysis, sanity checks)
  6→ * - Per-iteration token and duration limits
  7→ * - Cost-based limits with configurable thresholds
  8→ * - Configurable warning thresholds at percentages of limits
  9→ * - Detailed tracking of exceedances and warnings
 10→ */
 11→
 12→import { GuardrailsConfig } from '../types/config.js';
 13→import { AnalysisRun, PhaseMetrics, PhaseMetric, IterationMetrics, GuardrailEnforcement, GuardrailExceeded, GuardrailWarning } from '../types/state.js';
 14→
 15→export type PhaseType = 'discovery' | 'analysis' | 'sanityChecks';
 16→
 17→export interface GuardrailCheckResult {
 18→  canContinue: boolean;
 19→  warning?: string;
 20→  reason?: string;
 21→  warnings?: GuardrailWarning[];
 22→  exceedances?: GuardrailExceeded[];
 23→}
 24→
 25→export class GuardrailsManager {
 26→  private config: GuardrailsConfig;
 27→  private startTime: number;
 28→  private phaseStartTimes: Map<PhaseType, number> = new Map();
 29→  private currentPhase?: PhaseType;
 30→  private currentIteration: number = 0;
 31→  private iterationStartTime?: number;
 32→
 33→  constructor(config?: GuardrailsConfig) {
 34→    this.config = config || {};
 35→    this.startTime = Date.now();
 36→  }
 37→
 38→  /**
 39→   * Begin tracking a new phase
 40→   */
 41→  public startPhase(phase: PhaseType): void {
 42→    this.currentPhase = phase;
 43→    this.phaseStartTimes.set(phase, Date.now());
 44→  }
 45→
 46→  /**
 47→   * End tracking current phase and record metrics
 48→   */
 49→  public endPhase(run: AnalysisRun, phase: PhaseType): void {
 50→    if (!run.phaseMetrics) {
 51→      run.phaseMetrics = {};
 52→    }
 53→
 54→    const startTime = this.phaseStartTimes.get(phase);
 55→    if (startTime) {
 56→      const metric: PhaseMetric = {
 57→        startedAt: new Date(startTime).toISOString(),
 58→        completedAt: new Date().toISOString(),
 59→        tokensUsed: this.getPhaseTokens(run, phase),
 60→        estimatedCost: this.getPhaseCost(run, phase)
 61→      };
 62→
 63→      if (phase === 'discovery') {
 64→        run.phaseMetrics.discovery = metric;
 65→      } else if (phase === 'analysis') {
 66→        run.phaseMetrics.analysis = metric;
 67→      } else if (phase === 'sanityChecks') {
 68→        run.phaseMetrics.sanityChecks = metric;
 69→      }
 70→    }
 71→
 72→    this.currentPhase = undefined;
 73→  }
 74→
 75→  /**
 76→   * Start tracking a new iteration
 77→   */
 78→  public startIteration(iteration: number): void {
 79→    this.currentIteration = iteration;
 80→    this.iterationStartTime = Date.now();
 81→  }
 82→
 83→  /**
 84→   * End tracking current iteration and record metrics
 85→   */
 86→  public endIteration(run: AnalysisRun, iteration: number): void {
 87→    if (!run.iterationMetrics) {
 88→      run.iterationMetrics = [];
 89→    }
 90→
 91→    if (this.iterationStartTime) {
 92→      const metric: IterationMetrics = {
 93→        iterationNumber: iteration,
 94→        startedAt: new Date(this.iterationStartTime).toISOString(),
 95→        completedAt: new Date().toISOString(),
 96→        tokensUsed: run.totalTokensUsed || 0,
 97→        estimatedCost: run.estimatedCost || 0,
 98→        duration: Date.now() - this.iterationStartTime
 99→      };
100→
101→      run.iterationMetrics.push(metric);
102→    }
103→
104→    this.iterationStartTime = undefined;
105→  }
106→
107→  /**
108→   * Check all guardrails and return enforcement status
109→   */
110→  public checkGuardrails(run: AnalysisRun): GuardrailCheckResult {
111→    // If guardrails disabled, allow continuation
112→    if (this.config.enabled === false) {
113→      return { canContinue: true };
114→    }
115→
116→    const elapsedSeconds = (Date.now() - this.startTime) / 1000;
117→    const totalTokens = run.totalTokensUsed || 0;
118→    const totalCost = run.estimatedCost || 0;
119→
120→    // Get default thresholds
121→    const warnThresholds = this.config.warnThresholds || {};
122→    const tokenWarnPercent = warnThresholds.tokenPercentage ?? 80;
123→    const durationWarnPercent = warnThresholds.durationPercentage ?? 80;
124→    const costWarnPercent = warnThresholds.costPercentage ?? 80;
125→    const iterationTokenWarnPercent = warnThresholds.iterationTokenPercentage ?? 80;
126→    const phaseTokenWarnPercent = warnThresholds.phaseTokenPercentage ?? 80;
127→
128→    const warnings: GuardrailWarning[] = [];
129→    const exceedances: GuardrailExceeded[] = [];
130→
131→    // 1. Check hard limits - STOP
132→    if (this.config.maxTokensPerRun && totalTokens >= this.config.maxTokensPerRun) {
133→      exceedances.push({
134→        type: 'tokens_per_run',
135→        limit: this.config.maxTokensPerRun,
136→        actual: totalTokens,
137→        unit: 'tokens'
138→      });
139→      return this.createStopResult(
140→        `Token limit exceeded: ${totalTokens.toLocaleString()} / ${this.config.maxTokensPerRun.toLocaleString()} tokens`,
141→        warnings,
142→        exceedances
143→      );
144→    }
145→
146→    if (this.config.maxDurationSeconds && elapsedSeconds >= this.config.maxDurationSeconds) {
147→      exceedances.push({
148→        type: 'duration',
149→        limit: this.config.maxDurationSeconds,
150→        actual: Math.round(elapsedSeconds),
151→        unit: 'seconds'
152→      });
153→      return this.createStopResult(
154→        `Duration limit exceeded: ${Math.round(elapsedSeconds)}s / ${this.config.maxDurationSeconds}s`,
155→        warnings,
156→        exceedances
157→      );
158→    }
159→
160→    if (this.config.maxCostDollars && totalCost >= this.config.maxCostDollars) {
161→      exceedances.push({
162→        type: 'cost',
163→        limit: this.config.maxCostDollars,
164→        actual: Number(totalCost.toFixed(2)),
165→        unit: 'dollars'
166→      });
167→      return this.createStopResult(
168→        `Cost limit exceeded: $${totalCost.toFixed(2)} / $${this.config.maxCostDollars.toFixed(2)}`,
169→        warnings,
170→        exceedances
171→      );
172→    }
173→
174→    // 2. Check phase-specific token limits
175→    if (this.currentPhase && this.config.maxTokensPerPhase) {
176→      const phaseLimits = this.config.maxTokensPerPhase;
177→      let phaseLimit: number | undefined;
178→      let phaseTokens: number | undefined;
179→
180→      if (this.currentPhase === 'discovery' && phaseLimits.discovery) {
181→        phaseLimit = phaseLimits.discovery;
182→        phaseTokens = this.getPhaseTokens(run, 'discovery');
183→      } else if (this.currentPhase === 'analysis' && phaseLimits.analysis) {
184→        phaseLimit = phaseLimits.analysis;
185→        phaseTokens = this.getPhaseTokens(run, 'analysis');
186→      } else if (this.currentPhase === 'sanityChecks' && phaseLimits.sanityChecks) {
187→        phaseLimit = phaseLimits.sanityChecks;
188→        phaseTokens = this.getPhaseTokens(run, 'sanityChecks');
189→      }
190→
191→      if (phaseLimit && phaseTokens !== undefined && phaseTokens >= phaseLimit) {
192→        if (this.config.stopOnExceeded !== false) {
193→          exceedances.push({
194→            type: 'tokens_per_phase',
195→            phase: this.currentPhase,
196→            limit: phaseLimit,
197→            actual: phaseTokens,
198→            unit: 'tokens'
199→          });
200→          return this.createStopResult(
201→            `Phase token limit exceeded (${this.currentPhase}): ${phaseTokens.toLocaleString()} / ${phaseLimit.toLocaleString()} tokens`,
202→            warnings,
203→            exceedances
204→          );
205→        }
206→      }
207→    }
208→
209→    // 3. Check per-iteration limits
210→    if (this.currentIteration > 0 && this.config.maxTokensPerIteration) {
211→      const iterationTokens = this.getCurrentIterationTokens(run);
212→      if (iterationTokens >= this.config.maxTokensPerIteration) {
213→        if (this.config.stopOnExceeded !== false) {
214→          exceedances.push({
215→            type: 'tokens_per_iteration',
216→            iteration: this.currentIteration,
217→            limit: this.config.maxTokensPerIteration,
218→            actual: iterationTokens,
219→            unit: 'tokens'
220→          });
221→          return this.createStopResult(
222→            `Iteration token limit exceeded (iteration ${this.currentIteration}): ${iterationTokens.toLocaleString()} / ${this.config.maxTokensPerIteration.toLocaleString()} tokens`,
223→            warnings,
224→            exceedances
225→          );
226→        }
227→      }
228→    }
229→
230→    if (this.currentIteration > 0 && this.iterationStartTime && this.config.maxIterationDurationSeconds) {
231→      const iterationDuration = (Date.now() - this.iterationStartTime) / 1000;
232→      if (iterationDuration >= this.config.maxIterationDurationSeconds) {
233→        if (this.config.stopOnExceeded !== false) {
234→          exceedances.push({
235→            type: 'iteration_duration',
236→            iteration: this.currentIteration,
237→            limit: this.config.maxIterationDurationSeconds,
238→            actual: Math.round(iterationDuration),
239→            unit: 'seconds'
240→          });
241→          return this.createStopResult(
242→            `Iteration duration exceeded (iteration ${this.currentIteration}): ${Math.round(iterationDuration)}s / ${this.config.maxIterationDurationSeconds}s`,
243→            warnings,
244→            exceedances
245→          );
246→        }
247→      }
248→    }
249→
250→    // 4. Check warning thresholds
251→    if (this.config.maxTokensPerRun) {
252→      const tokenPercent = (totalTokens / this.config.maxTokensPerRun) * 100;
253→      if (tokenPercent >= tokenWarnPercent) {
254→        warnings.push({
255→          type: 'tokens_per_run',
256→          percentage: Math.round(tokenPercent),
257→          message: `Token usage at ${Math.round(tokenPercent)}% (${totalTokens.toLocaleString()} / ${this.config.maxTokensPerRun.toLocaleString()})`
258→        });
259→      }
260→    }
261→
262→    if (this.config.maxDurationSeconds) {
263→      const durationPercent = (elapsedSeconds / this.config.maxDurationSeconds) * 100;
264→      if (durationPercent >= durationWarnPercent) {
265→        warnings.push({
266→          type: 'duration',
267→          percentage: Math.round(durationPercent),
268→          message: `Duration at ${Math.round(durationPercent)}% (${Math.round(elapsedSeconds)}s / ${this.config.maxDurationSeconds}s)`
269→        });
270→      }
271→    }
272→
273→    if (this.config.maxCostDollars) {
274→      const costPercent = (totalCost / this.config.maxCostDollars) * 100;
275→      if (costPercent >= costWarnPercent) {
276→        warnings.push({
277→          type: 'cost',
278→          percentage: Math.round(costPercent),
279→          message: `Cost at ${Math.round(costPercent)}% ($${totalCost.toFixed(2)} / $${this.config.maxCostDollars.toFixed(2)})`
280→        });
281→      }
282→    }
283→
284→    if (this.currentPhase && this.config.maxTokensPerPhase) {
285→      const phaseLimits = this.config.maxTokensPerPhase;
286→      let phaseLimit: number | undefined;
287→      let phaseTokens: number | undefined;
288→
289→      if (this.currentPhase === 'discovery' && phaseLimits.discovery) {
290→        phaseLimit = phaseLimits.discovery;
291→        phaseTokens = this.getPhaseTokens(run, 'discovery');
292→      } else if (this.currentPhase === 'analysis' && phaseLimits.analysis) {
293→        phaseLimit = phaseLimits.analysis;
294→        phaseTokens = this.getPhaseTokens(run, 'analysis');
295→      } else if (this.currentPhase === 'sanityChecks' && phaseLimits.sanityChecks) {
296→        phaseLimit = phaseLimits.sanityChecks;
297→        phaseTokens = this.getPhaseTokens(run, 'sanityChecks');
298→      }
299→
300→      if (phaseLimit && phaseTokens !== undefined) {
301→        const phaseTokenPercent = (phaseTokens / phaseLimit) * 100;
302→        if (phaseTokenPercent >= phaseTokenWarnPercent) {
303→          warnings.push({
304→            type: 'tokens_per_phase',
305→            phase: this.currentPhase,
306→            percentage: Math.round(phaseTokenPercent),
307→            message: `Phase token usage at ${Math.round(phaseTokenPercent)}% (${phaseTokens.toLocaleString()} / ${phaseLimit.toLocaleString()})`
308→          });
309→        }
310→      }
311→    }
312→
313→    if (this.currentIteration > 0 && this.config.maxTokensPerIteration) {
314→      const iterationTokens = this.getCurrentIterationTokens(run);
315→      const iterationTokenPercent = (iterationTokens / this.config.maxTokensPerIteration) * 100;
316→      if (iterationTokenPercent >= iterationTokenWarnPercent) {
317→        warnings.push({
318→          type: 'tokens_per_iteration',
319→          iteration: this.currentIteration,
320→          percentage: Math.round(iterationTokenPercent),
321→          message: `Iteration token usage at ${Math.round(iterationTokenPercent)}% (${iterationTokens.toLocaleString()} / ${this.config.maxTokensPerIteration.toLocaleString()})`
322→        });
323→      }
324→    }
325→
326→    return {
327→      canContinue: true,
328→      warnings: warnings.length > 0 ? warnings : undefined,
329→      exceedances: exceedances.length > 0 ? exceedances : undefined
330→    };
331→  }
332→
333→  /**
334→   * Record guardrail enforcement in the run
335→   */
336→  public recordEnforcement(run: AnalysisRun, result: GuardrailCheckResult): void {
337→    if (!result.warnings && !result.exceedances && result.canContinue) {
338→      return; // Nothing to record
339→    }
340→
341→    if (!run.guardrailsEnforced) {
342→      run.guardrailsEnforced = {
343→        exceedances: [],
344→        warnings: []
345→      };
346→    }
347→
348→    if (result.exceedances) {
349→      run.guardrailsEnforced.exceedances.push(...result.exceedances);
350→      run.guardrailsEnforced.stoppedDueToGuardrails = true;
351→      run.guardrailsEnforced.stoppedReason = result.reason;
352→    }
353→
354→    if (result.warnings) {
355→      run.guardrailsEnforced.warnings.push(...result.warnings);
356→    }
357→  }
358→
359→  /**
360→   * Get tokens used in a specific phase
361→   */
362→  private getPhaseTokens(run: AnalysisRun, phase: PhaseType): number {
363→    if (!run.phaseMetrics) return 0;
364→
365→    if (phase === 'discovery') {
366→      return run.phaseMetrics.discovery?.tokensUsed || 0;
367→    } else if (phase === 'analysis') {
368→      return run.phaseMetrics.analysis?.tokensUsed || 0;
369→    } else if (phase === 'sanityChecks') {
370→      return run.phaseMetrics.sanityChecks?.tokensUsed || 0;
371→    }
372→
373→    return 0;
374→  }
375→
376→  /**
377→   * Get estimated cost for a specific phase
378→   */
379→  private getPhaseCost(run: AnalysisRun, phase: PhaseType): number {
380→    if (!run.phaseMetrics) return 0;
381→
382→    if (phase === 'discovery') {
383→      return run.phaseMetrics.discovery?.estimatedCost || 0;
384→    } else if (phase === 'analysis') {
385→      return run.phaseMetrics.analysis?.estimatedCost || 0;
386→    } else if (phase === 'sanityChecks') {
387→      return run.phaseMetrics.sanityChecks?.estimatedCost || 0;
388→    }
389→
390→    return 0;
391→  }
392→
393→  /**
394→   * Get tokens used in current iteration
395→   */
396→  private getCurrentIterationTokens(run: AnalysisRun): number {
397→    if (!run.iterationMetrics || run.iterationMetrics.length === 0) {
398→      return 0;
399→    }
400→
401→    // Return tokens for current iteration only (latest entry)
402→    const currentMetric = run.iterationMetrics[run.iterationMetrics.length - 1];
403→    return currentMetric.tokensUsed || 0;
404→  }
