406→  /**
407→   * Create a stop result with warnings and exceedances
408→   */
409→  private createStopResult(
410→    reason: string,
411→    warnings: GuardrailWarning[],
412→    exceedances: GuardrailExceeded[]
413→  ): GuardrailCheckResult {
414→    return {
415→      canContinue: false,
416→      reason,
417→      warnings: warnings.length > 0 ? warnings : undefined,
418→      exceedances: exceedances.length > 0 ? exceedances : undefined
419→    };
420→  }
421→
422→  /**
423→   * Get current elapsed time in seconds
424→   */
425→  public getElapsedSeconds(): number {
426→    return (Date.now() - this.startTime) / 1000;
427→  }
