429→  /**
430→   * Get current phase token budget (remaining tokens)
431→   */
432→  public getPhaseTokenBudgetRemaining(phase: PhaseType): number | undefined {
433→    if (!this.config.maxTokensPerPhase) return undefined;
434→
435→    const limit = this.config.maxTokensPerPhase[phase];
436→    if (!limit) return undefined;
437→
438→    // This would need access to the current run to calculate remaining
439→    // For now, just return the limit
440→    return limit;
441→  }
