   1→/**
   2→ * Main analysis orchestrator
   3→ * Coordinates the entire documentation generation workflow
   4→ */
   5→
   6→import { DatabaseDocumentation, AnalysisRun, SchemaDefinition, TableDefinition, ColumnDefinition } from '../types/state.js';
   7→import { TableNode, BackpropagationTrigger, TableAnalysisContext } from '../types/analysis.js';
   8→import {
   9→  TableAnalysisPromptResult,
  10→  SchemaSanityCheckPromptResult,
  11→  CrossSchemaSanityCheckPromptResult,
  12→  SemanticComparisonPromptResult,
  13→  DependencyLevelSanityCheckResult,
  14→  SchemaLevelSanityCheckResult,
  15→  CrossSchemaSanityCheckResult
  16→} from '../types/prompts.js';
  17→import { DBAutoDocConfig } from '../types/config.js';
  18→import { PromptEngine } from '../prompts/PromptEngine.js';
  19→import { StateManager } from '../state/StateManager.js';
  20→import { IterationTracker } from '../state/IterationTracker.js';
  21→import { BackpropagationEngine } from './BackpropagationEngine.js';
  22→import { ConvergenceDetector } from './ConvergenceDetector.js';
  23→import { GuardrailsManager } from './GuardrailsManager.js';
  24→
  25→export class AnalysisEngine {
  26→  private backpropagationEngine: BackpropagationEngine;
  27→  private convergenceDetector: ConvergenceDetector;
  28→  private guardrailsManager: GuardrailsManager;
  29→  private startTime: number = 0;
  30→  private currentRun?: AnalysisRun;
  31→
  32→  constructor(
  33→    private config: DBAutoDocConfig,
  34→    private promptEngine: PromptEngine,
  35→    private stateManager: StateManager,
  36→    private iterationTracker: IterationTracker
  37→  ) {
  38→    this.backpropagationEngine = new BackpropagationEngine(
  39→      promptEngine,
  40→      stateManager,
  41→      iterationTracker,
  42→      config.analysis.backpropagation.maxDepth
  43→    );
  44→
  45→    this.convergenceDetector = new ConvergenceDetector(
  46→      config.analysis.convergence,
  47→      stateManager,
  48→      iterationTracker
  49→    );
  50→
  51→    this.guardrailsManager = new GuardrailsManager(config.analysis.guardrails);
  52→
  53→    // Set up guardrail checking in PromptEngine
  54→    this.promptEngine.setGuardrailCheck(() => {
  55→      if (!this.currentRun) {
  56→        return { canContinue: true };
  57→      }
  58→      const result = this.guardrailsManager.checkGuardrails(this.currentRun);
  59→      this.guardrailsManager.recordEnforcement(this.currentRun, result);
  60→      return result;
  61→    });
  62→  }
  63→
  64→  /**
  65→   * Initialize timing for guardrails and set current run
  66→   */
  67→  public startAnalysis(run: AnalysisRun): void {
  68→    this.startTime = Date.now();
  69→    this.currentRun = run;
  70→    this.guardrailsManager.startPhase('analysis');
  71→  }
  72→
  73→  /**
  74→   * Process a single dependency level
  75→   */
  76→  public async processLevel(
  77→    state: DatabaseDocumentation,
  78→    run: AnalysisRun,
  79→    level: number,
  80→    tables: TableNode[]
  81→  ): Promise<BackpropagationTrigger[]> {
  82→    const triggers: BackpropagationTrigger[] = [];
  83→
  84→    for (const tableNode of tables) {
  85→      const result = await this.analyzeTable(state, run, tableNode, level);
  86→
  87→      // Check if guardrail was exceeded during this table's analysis
  88→      if (result.guardrailExceeded) {
  89→        break; // Stop processing this level
  90→      }
  91→
  92→      if (result.triggers) {
  93→        triggers.push(...result.triggers);
  94→      }
  95→    }
  96→
  97→    run.levelsProcessed = Math.max(run.levelsProcessed, level + 1);
  98→
  99→    return triggers;
 100→  }
