 102→  /**
 103→   * Analyze a single table
 104→   */
 105→  private async analyzeTable(
 106→    state: DatabaseDocumentation,
 107→    run: AnalysisRun,
 108→    tableNode: TableNode,
 109→    level: number
 110→  ): Promise<{ triggers?: BackpropagationTrigger[]; guardrailExceeded?: boolean }> {
 111→    const table = tableNode.tableDefinition;
 112→    if (!table) {
 113→      return {};
 114→    }
 115→
 116→    try {
 117→      // Build analysis context
 118→      const context = this.buildTableContext(state, tableNode);
 119→
 120→      // Execute analysis prompt
 121→      const result = await this.promptEngine.executePrompt<TableAnalysisPromptResult>(
 122→        'table-analysis',
 123→        context,
 124→        {
 125→          responseFormat: 'JSON',
 126→          temperature: this.config.ai.temperature
 127→        }
 128→      );
 129→
 130→      // Check if guardrail was exceeded
 131→      if (result.guardrailExceeded) {
 132→        this.iterationTracker.completeRun(run, false, result.errorMessage || 'Guardrail exceeded');
 133→        return { guardrailExceeded: true };
 134→      }
 135→
 136→      if (!result.success || !result.result) {
 137→        this.iterationTracker.addError(
 138→          run,
 139→          `Failed to analyze ${tableNode.schema}.${tableNode.table}: ${result.errorMessage}`
 140→        );
 141→
 142→        this.iterationTracker.addLogEntryWithPrompt(
 143→          run,
 144→          {
 145→            level,
 146→            schema: tableNode.schema,
 147→            table: tableNode.table,
 148→            action: 'analyze',
 149→            result: 'error',
 150→            message: result.errorMessage
 151→          },
 152→          result.promptInput,
 153→          result.promptOutput
 154→        );
 155→
 156→        return {};
 157→      }
 158→
 159→      // Track tokens
 160→      this.iterationTracker.addTokenUsage(run, result.tokensUsed, result.cost);
 161→
 162→      // Use semantic comparison to check if description materially changed
 163→      const previousDescription = table.description;
 164→      const comparisonResult = await this.compareDescriptions(
 165→        run,
 166→        table,
 167→        result.result,
 168→        tableNode.schema,
 169→        tableNode.table
 170→      );
 171→      const descriptionChanged = comparisonResult.tableMateriallyChanged;
 172→
 173→      // Update table description
 174→      this.stateManager.updateTableDescription(
 175→        table,
 176→        result.result.tableDescription,
 177→        result.result.reasoning,
 178→        result.result.confidence,
 179→        run.modelUsed,
 180→        previousDescription ? 'refinement' : 'initial'
 181→      );
 182→
 183→      // Update column descriptions
 184→      for (const colDesc of result.result.columnDescriptions || []) {
 185→        const column = table.columns.find(c => c.name === colDesc.columnName);
 186→        if (column) {
 187→          this.stateManager.updateColumnDescription(
 188→            column,
 189→            colDesc.description,
 190→            colDesc.reasoning,
 191→            run.modelUsed
 192→          );
 193→        }
 194→      }
 195→
 196→      // Process structured FK insights from LLM and feed back to discovery phase
 197→      if (state.phases.keyDetection && result.result.foreignKeys) {
 198→        this.processFKInsightsFromLLM(
 199→          state,
 200→          tableNode.schema,
 201→          tableNode.table,
 202→          result.result.foreignKeys
 203→        );
 204→      }
 205→
 206→      // Update inferred business domain
 207→      if (result.result.inferredBusinessDomain) {
 208→        // Could store this in table metadata if needed
 209→      }
 210→
 211→      // Log result with prompt I/O and semantic comparison details
 212→      this.iterationTracker.addLogEntryWithPrompt(
 213→        run,
 214→        {
 215→          level,
 216→          schema: tableNode.schema,
 217→          table: tableNode.table,
 218→          action: 'analyze',
 219→          result: descriptionChanged ? 'changed' : 'unchanged',
 220→          message: `Confidence: ${result.result.confidence.toFixed(2)}`,
 221→          tokensUsed: result.tokensUsed,
 222→          semanticComparison: comparisonResult
 223→        },
 224→        result.promptInput,
 225→        result.promptOutput
 226→      );
 227→
 228→      // Detect potential insights for parent tables
 229→      const triggers = this.backpropagationEngine.detectParentInsights(
 230→        table,
 231→        result.result,
 232→        tableNode.schema,
 233→        tableNode.table
 234→      );
 235→
 236→      return { triggers };
 237→
 238→    } catch (error) {
 239→      this.iterationTracker.addError(
 240→        run,
 241→        `Exception analyzing ${tableNode.schema}.${tableNode.table}: ${(error as Error).message}`
 242→      );
 243→
 244→      this.iterationTracker.addLogEntry(run, {
 245→        level,
 246→        schema: tableNode.schema,
 247→        table: tableNode.table,
 248→        action: 'analyze',
 249→        result: 'error',
 250→        message: (error as Error).message
 251→      });
 252→
 253→      return {};
 254→    }
 255→  }
