 257→  /**
 258→   * Build context for table analysis
 259→   */
 260→  private buildTableContext(
 261→    state: DatabaseDocumentation,
 262→    tableNode: TableNode
 263→  ): TableAnalysisContext {
 264→    const table = tableNode.tableDefinition!;
 265→
 266→    // Get parent table descriptions (for context)
 267→    const parentDescriptions = table.dependsOn
 268→      .map(dep => {
 269→        const parentTable = this.stateManager.findTable(state, dep.schema, dep.table);
 270→        if (parentTable && parentTable.description) {
 271→          return {
 272→            schema: dep.schema,
 273→            table: dep.table,
 274→            description: parentTable.description
 275→          };
 276→        }
 277→        return null;
 278→      })
 279→      .filter(p => p !== null);
 280→
 281→    // Build list of all tables in the database for FK reference validation
 282→    const allTables: Array<{ schema: string; name: string }> = [];
 283→    for (const schema of state.schemas) {
 284→      for (const tbl of schema.tables) {
 285→        allTables.push({ schema: schema.name, name: tbl.name });
 286→      }
 287→    }
 288→
 289→    return {
 290→      schema: tableNode.schema,
 291→      table: tableNode.table,
 292→      rowCount: table.rowCount,
 293→      columns: table.columns.map(col => ({
 294→        name: col.name,
 295→        dataType: col.dataType,
 296→        isNullable: col.isNullable,
 297→        isPrimaryKey: col.isPrimaryKey,
 298→        isForeignKey: col.isForeignKey,
 299→        foreignKeyReferences: col.foreignKeyReferences,
 300→        checkConstraint: col.checkConstraint,
 301→        defaultValue: col.defaultValue,
 302→        possibleValues: col.possibleValues,
 303→        statistics: col.statistics
 304→      })),
 305→      dependsOn: table.dependsOn,
 306→      dependents: table.dependents,
 307→      sampleData: [], // Could add sample rows here if needed
 308→      parentDescriptions: parentDescriptions as any,
 309→      userNotes: table.userNotes,
 310→      seedContext: state.seedContext,
 311→      allTables
 312→    };
 313→  }
 314→
 315→  /**
 316→   * Compare descriptions using LLM to determine material changes
 317→   */
 318→  private async compareDescriptions(
 319→    run: AnalysisRun,
 320→    table: TableDefinition,
 321→    newResult: TableAnalysisPromptResult,
 322→    schemaName: string,
 323→    tableName: string
 324→  ): Promise<SemanticComparisonPromptResult> {
 325→    // Get previous iteration
 326→    const previousIteration = table.descriptionIterations.length > 0
 327→      ? table.descriptionIterations[table.descriptionIterations.length - 1]
 328→      : null;
 329→
 330→    // If no previous iteration, it's initial generation - don't waste tokens on comparison
 331→    // Return minimal result with no column changes (they'll all be logged as "initial" anyway)
 332→    if (!previousIteration) {
 333→      return {
 334→        tableMateriallyChanged: true,
 335→        tableChangeReasoning: 'Initial generation (skipped semantic comparison)',
 336→        columnChanges: [] // Don't log individual column changes for initial generation
 337→      };
 338→    }
 339→
 340→    // Build previous column descriptions map
 341→    const previousColumns = table.columns.map(col => ({
 342→      columnName: col.name,
 343→      description: col.description || ''
 344→    }));
 345→
 346→    // Build current column descriptions
 347→    const currentColumns = newResult.columnDescriptions.map(col => ({
 348→      columnName: col.columnName,
 349→      description: col.description
 350→    }));
 351→
 352→    // Call semantic comparison prompt
 353→    const result = await this.promptEngine.executePrompt<SemanticComparisonPromptResult>(
 354→      'semantic-comparison',
 355→      {
 356→        schemaName,
 357→        tableName,
 358→        previousIteration: table.descriptionIterations.length,
 359→        currentIteration: table.descriptionIterations.length + 1,
 360→        previousTableDescription: previousIteration.description,
 361→        previousColumns,
 362→        currentTableDescription: newResult.tableDescription,
 363→        currentColumns
 364→      },
 365→      {
 366→        responseFormat: 'JSON'
 367→      }
 368→    );
 369→
 370→    if (!result.success || !result.result) {
 371→      // If comparison fails, assume changed to be safe
 372→      return {
 373→        tableMateriallyChanged: true,
 374→        tableChangeReasoning: 'Comparison failed - assuming changed for safety',
 375→        columnChanges: newResult.columnDescriptions.map(col => ({
 376→          columnName: col.columnName,
 377→          materiallyChanged: true,
 378→          changeReasoning: 'Comparison failed'
 379→        }))
 380→      };
 381→    }
 382→
 383→    // Track tokens for comparison
 384→    this.iterationTracker.addTokenUsage(run, result.tokensUsed, result.cost);
 385→
 386→    return result.result;
 387→  }
