 389→  /**
 390→   * Perform dependency-level sanity check
 391→   * Checks consistency across tables at the same dependency level
 392→   */
 393→  public async performDependencyLevelSanityCheck(
 394→    state: DatabaseDocumentation,
 395→    run: AnalysisRun,
 396→    level: number,
 397→    tables: TableNode[]
 398→  ): Promise<boolean> {
 399→    try {
 400→      const context = {
 401→        dependencyLevel: level,
 402→        tables: tables.map(t => {
 403→          const tableDef = t.tableDefinition;
 404→          return {
 405→            schema: t.schema,
 406→            table: t.table,
 407→            description: tableDef?.description || 'No description yet',
 408→            columns: tableDef?.columns.map(c => ({
 409→              name: c.name,
 410→              description: c.description || 'No description yet'
 411→            })) || [],
 412→            dependsOn: tableDef?.dependsOn || [],
 413→            dependents: tableDef?.dependents || []
 414→          };
 415→        })
 416→      };
 417→
 418→      const result = await this.promptEngine.executePrompt<DependencyLevelSanityCheckResult>(
 419→        'dependency-level-sanity-check',
 420→        context,
 421→        {
 422→          responseFormat: 'JSON'
 423→        }
 424→      );
 425→
 426→      if (result.success && result.result) {
 427→        // Track this sanity check
 428→        const sanityCheckRecord = {
 429→          timestamp: new Date().toISOString(),
 430→          checkType: 'dependency_level' as const,
 431→          scope: `level ${level}`,
 432→          hasMaterialIssues: result.result.hasMaterialIssues,
 433→          issuesFound: result.result.tableIssues.length,
 434→          tablesAffected: result.result.tableIssues.map(i => i.tableName),
 435→          result: result.result.hasMaterialIssues ? 'issues_corrected' as const : 'no_issues' as const,
 436→          tokensUsed: result.tokensUsed,
 437→          promptInput: result.promptInput,
 438→          promptOutput: result.promptOutput
 439→        };
 440→
 441→        run.sanityChecks.push(sanityCheckRecord);
 442→        run.sanityCheckCount++;
 443→
 444→        // Track tokens
 445→        this.iterationTracker.addTokenUsage(run, result.tokensUsed, result.cost);
 446→
 447→        // Log issues
 448→        if (result.result.hasMaterialIssues) {
 449→          for (const issue of result.result.tableIssues) {
 450→            this.iterationTracker.addWarning(
 451→              run,
 452→              `[Level ${level}] ${issue.severity.toUpperCase()}: ${issue.tableName} - ${issue.description}`
 453→            );
 454→          }
 455→        }
 456→
 457→        return result.result.hasMaterialIssues;
 458→      }
 459→
 460→      return false;
 461→    } catch (error) {
 462→      this.iterationTracker.addError(
 463→        run,
 464→        `Dependency-level sanity check failed for level ${level}: ${(error as Error).message}`
 465→      );
 466→      return false;
 467→    }
 468→  }
