 470→  /**
 471→   * Perform schema-level sanity check
 472→   * Holistic review after entire schema is analyzed
 473→   */
 474→  public async performSchemaLevelSanityCheck(
 475→    state: DatabaseDocumentation,
 476→    run: AnalysisRun,
 477→    schema: SchemaDefinition
 478→  ): Promise<boolean> {
 479→    try {
 480→      const context = {
 481→        schemaName: schema.name,
 482→        tables: schema.tables.map(t => ({
 483→          name: t.name,
 484→          description: t.description || 'No description yet',
 485→          rowCount: t.rowCount,
 486→          dependencyLevel: t.dependencyLevel,
 487→          columns: t.columns.map(c => ({
 488→            name: c.name,
 489→            dataType: c.dataType,
 490→            description: c.description || 'No description yet'
 491→          })),
 492→          dependsOn: t.dependsOn,
 493→          dependents: t.dependents
 494→        }))
 495→      };
 496→
 497→      const result = await this.promptEngine.executePrompt<SchemaLevelSanityCheckResult>(
 498→        'schema-level-sanity-check',
 499→        context,
 500→        {
 501→          responseFormat: 'JSON'
 502→        }
 503→      );
 504→
 505→      if (result.success && result.result) {
 506→        // Update schema description if provided
 507→        if (result.result.schemaLevelIssues.some(i => i.suggestedSchemaDescription)) {
 508→          const suggested = result.result.schemaLevelIssues.find(i => i.suggestedSchemaDescription);
 509→          if (suggested?.suggestedSchemaDescription) {
 510→            this.stateManager.updateSchemaDescription(
 511→              schema,
 512→              suggested.suggestedSchemaDescription,
 513→              'Generated from schema-level sanity check',
 514→              run.modelUsed
 515→            );
 516→          }
 517→        }
 518→
 519→        // Track this sanity check
 520→        const sanityCheckRecord = {
 521→          timestamp: new Date().toISOString(),
 522→          checkType: 'schema_level' as const,
 523→          scope: `${schema.name} schema`,
 524→          hasMaterialIssues: result.result.hasMaterialIssues,
 525→          issuesFound: result.result.schemaLevelIssues.length + result.result.tableIssues.length,
 526→          tablesAffected: [
 527→            ...result.result.tableIssues.map(i => i.tableName),
 528→            ...result.result.schemaLevelIssues.flatMap(i => i.affectedTables)
 529→          ],
 530→          result: result.result.hasMaterialIssues ? 'issues_corrected' as const : 'no_issues' as const,
 531→          tokensUsed: result.tokensUsed,
 532→          promptInput: result.promptInput,
 533→          promptOutput: result.promptOutput
 534→        };
 535→
 536→        run.sanityChecks.push(sanityCheckRecord);
 537→        run.sanityCheckCount++;
 538→
 539→        // Track tokens
 540→        this.iterationTracker.addTokenUsage(run, result.tokensUsed, result.cost);
 541→
 542→        // Log issues
 543→        if (result.result.hasMaterialIssues) {
 544→          for (const issue of result.result.schemaLevelIssues) {
 545→            this.iterationTracker.addWarning(
 546→              run,
 547→              `[Schema ${schema.name}] ${issue.severity.toUpperCase()}: ${issue.issueType} - ${issue.description}`
 548→            );
 549→          }
 550→          for (const issue of result.result.tableIssues) {
 551→            this.iterationTracker.addWarning(
 552→              run,
 553→              `[Schema ${schema.name}] ${issue.severity.toUpperCase()}: ${issue.tableName} - ${issue.description}`
 554→            );
 555→          }
 556→        }
 557→
 558→        return result.result.hasMaterialIssues;
 559→      }
 560→
 561→      return false;
 562→    } catch (error) {
 563→      this.iterationTracker.addError(
 564→        run,
 565→        `Schema-level sanity check failed for ${schema.name}: ${(error as Error).message}`
 566→      );
 567→      return false;
 568→    }
 569→  }
