 596→
 597→      const result = await this.promptEngine.executePrompt<CrossSchemaSanityCheckResult>(
 598→        'cross-schema-sanity-check',
 599→        context,
 600→        {
 601→          responseFormat: 'JSON'
 602→        }
 603→      );
 604→
 605→      if (result.success && result.result) {
 606→        // Track this sanity check
 607→        const sanityCheckRecord = {
 608→          timestamp: new Date().toISOString(),
 609→          checkType: 'cross_schema' as const,
 610→          scope: 'all schemas',
 611→          hasMaterialIssues: result.result.hasMaterialIssues,
 612→          issuesFound: result.result.crossSchemaIssues.length + result.result.schemaIssues.length,
 613→          tablesAffected: result.result.crossSchemaIssues.flatMap(i =>
 614→            i.affectedTables.map(t => `${t.schema}.${t.table}`)
 615→          ),
 616→          result: result.result.hasMaterialIssues ? 'issues_corrected' as const : 'no_issues' as const,
 617→          tokensUsed: result.tokensUsed,
 618→          promptInput: result.promptInput,
 619→          promptOutput: result.promptOutput
 620→        };
 621→
 622→        run.sanityChecks.push(sanityCheckRecord);
 623→        run.sanityCheckCount++;
 624→
 625→        // Track tokens
 626→        this.iterationTracker.addTokenUsage(run, result.tokensUsed, result.cost);
 627→
 628→        // Log issues
 629→        if (result.result.hasMaterialIssues) {
 630→          for (const issue of result.result.crossSchemaIssues) {
 631→            this.iterationTracker.addWarning(
 632→              run,
 633→              `[Cross-Schema] ${issue.severity.toUpperCase()}: ${issue.issueType} - ${issue.description}`
 634→            );
 635→          }
 636→          for (const issue of result.result.schemaIssues) {
 637→            this.iterationTracker.addWarning(
 638→              run,
 639→              `[Schema ${issue.schemaName}] ${issue.issueType} - ${issue.description}`
 640→            );
 641→          }
 642→        }
 643→
 644→        return result.result.hasMaterialIssues;
 645→      }
 646→
 647→      return false;
 648→    } catch (error) {
 649→      this.iterationTracker.addError(
 650→        run,
 651→        `Cross-schema sanity check failed: ${(error as Error).message}`
 652→      );
 653→      return false;
 654→    }
 655→  }
