 722→  /**
 723→   * Process structured FK insights from LLM and create feedback to discovery phase
 724→   *
 725→   * Uses the foreignKeys array from table-analysis prompt response instead of brittle regex parsing.
 726→   * Per architectural decision: use LLM for language understanding, deterministic code for processing.
 727→   */
 728→  private processFKInsightsFromLLM(
 729→    state: DatabaseDocumentation,
 730→    schemaName: string,
 731→    tableName: string,
 732→    foreignKeys: import('../types/prompts.js').ForeignKeyPromptResult[]
 733→  ): void {
 734→    const discoveryPhase = state.phases.keyDetection;
 735→    if (!discoveryPhase || !foreignKeys || foreignKeys.length === 0) return;
 736→
 737→    console.log(`[AnalysisEngine] Processing ${foreignKeys.length} structured FK insights from LLM for ${schemaName}.${tableName}`);
 738→
 739→    for (const fk of foreignKeys) {
 740→      const { columnName, referencesSchema, referencesTable, referencesColumn, confidence } = fk;
 741→
 742→      // Create feedback for this FK
 743→      const feedback: import('../types/discovery.js').AnalysisToDiscoveryFeedback = {
 744→        type: 'new_relationship',
 745→        evidence: `LLM-identified FK: ${columnName} -> ${referencesSchema}.${referencesTable}.${referencesColumn} (confidence: ${confidence})`,
 746→        tableName,
 747→        columnName,
 748→        affectedCandidates: [],
 749→        recommendation: 'add_new',
 750→        newRelationship: {
 751→          targetTable: `${referencesSchema}.${referencesTable}`,
 752→          targetColumn: referencesColumn
 753→        }
 754→      };
 755→
 756→      // Check if this column was incorrectly marked as a PK - reject it unless it's a surrogate key
 757→      const falsePK = discoveryPhase.discovered.primaryKeys.find(pk =>
 758→        pk.schemaName === schemaName &&
 759→        pk.tableName === tableName &&
 760→        pk.columnNames.includes(columnName)
 761→      );
 762→
 763→      if (falsePK) {
 764→        const columnLower = columnName.toLowerCase();
 765→        const tableLower = tableName.toLowerCase();
 766→        const isSurrogateKey =
 767→          columnLower === `${tableLower}_id` ||
 768→          columnLower === tableLower + 'id' ||
 769→          columnLower === 'id';
 770→
 771→        if (!isSurrogateKey) {
 772→          falsePK.status = 'rejected';
 773→          feedback.affectedCandidates.push(`PK:${schemaName}.${tableName}.${columnName}`);
 774→          const column = this.findColumnInState(state, schemaName, tableName, columnName);
 775→          if (column) column.isPrimaryKey = false;
 776→          console.log(`[AnalysisEngine] FK from LLM: ${schemaName}.${tableName}.${columnName} -> ${referencesSchema}.${referencesTable}, rejecting as PK`);
 777→        }
 778→      }
 779→
 780→      // Check if we already have this FK - boost confidence
 781→      const existingFK = discoveryPhase.discovered.foreignKeys.find(fk =>
 782→        fk.schemaName === schemaName &&
 783→        fk.sourceTable === tableName &&
 784→        fk.sourceColumn === columnName
 785→      );
 786→
 787→      if (existingFK && existingFK.status === 'candidate') {
 788→        existingFK.validatedByLLM = true;
 789→        existingFK.status = 'confirmed';
 790→        existingFK.confidence = Math.min(existingFK.confidence + 20, 100);
 791→        feedback.type = 'confidence_change';
 792→        feedback.newConfidence = existingFK.confidence;
 793→        feedback.affectedCandidates.push(`FK:${schemaName}.${tableName}.${columnName}`);
 794→
 795→        const column = this.findColumnInState(state, schemaName, tableName, columnName);
 796→        if (column) {
 797→          column.isForeignKey = true;
 798→          column.foreignKeyReferences = {
 799→            schema: referencesSchema,
 800→            table: referencesTable,
 801→            column: referencesColumn,
 802→            referencedColumn: referencesColumn
 803→          };
 804→        }
 805→
 806→        // Update table-level dependsOn and dependents arrays for ERD generation
 807→        this.updateTableDependencies(state, schemaName, tableName, referencesSchema, referencesTable, columnName, referencesColumn);
 808→
 809→        console.log(`[AnalysisEngine] Confirmed FK: ${schemaName}.${tableName}.${columnName} -> ${referencesSchema}.${referencesTable}.${referencesColumn}, confidence: ${existingFK.confidence}`);
 810→      } else {
 811→        // Create new FK from LLM insight
 812→        const newFK: import('../types/discovery.js').FKCandidate = {
 813→          schemaName,
 814→          sourceTable: tableName,
 815→          sourceColumn: columnName,
 816→          targetSchema: referencesSchema,
 817→          targetTable: referencesTable,
 818→          targetColumn: referencesColumn,
 819→          confidence: Math.round(confidence * 100),
 820→          evidence: {
 821→            namingMatch: 0.9,
 822→            valueOverlap: 0,
 823→            cardinalityRatio: 0,
 824→            dataTypeMatch: true,
 825→            nullPercentage: 0,
 826→            sampleSize: 0,
 827→            orphanCount: 0,
 828→            warnings: ['Created from structured LLM output']
 829→          },
 830→          discoveredInIteration: 1,
 831→          validatedByLLM: true,
 832→          status: 'confirmed'
 833→        };
 834→
 835→        discoveryPhase.discovered.foreignKeys.push(newFK);
 836→        feedback.newConfidence = newFK.confidence;
 837→        feedback.affectedCandidates.push(`FK:${schemaName}.${tableName}.${columnName}`);
 838→
 839→        const column = this.findColumnInState(state, schemaName, tableName, columnName);
 840→        if (column) {
 841→          column.isForeignKey = true;
 842→          column.foreignKeyReferences = {
 843→            schema: referencesSchema,
 844→            table: referencesTable,
 845→            column: referencesColumn,
 846→            referencedColumn: referencesColumn
 847→          };
 848→        }
 849→
 850→        // Update table-level dependsOn and dependents arrays for ERD generation
 851→        this.updateTableDependencies(state, schemaName, tableName, referencesSchema, referencesTable, columnName, referencesColumn);
 852→
 853→        console.log(`[AnalysisEngine] Created FK from LLM: ${schemaName}.${tableName}.${columnName} -> ${referencesSchema}.${referencesTable}.${referencesColumn}`);
 854→      }
 855→
 856→      discoveryPhase.feedbackFromAnalysis.push(feedback);
 857→    }
 858→  }
