 860→  /**
 861→   * Find a column in the state schemas
 862→   */
 863→  private findColumnInState(
 864→    state: DatabaseDocumentation,
 865→    schemaName: string,
 866→    tableName: string,
 867→    columnName: string
 868→  ): ColumnDefinition | null {
 869→    const schema = state.schemas.find(s => s.name === schemaName);
 870→    if (!schema) return null;
 871→
 872→    const table = schema.tables.find(t => t.name === tableName);
 873→    if (!table) return null;
 874→
 875→    return table.columns.find(c => c.name === columnName) || null;
 876→  }
 877→
 878→  /**
 879→   * Update table-level dependsOn and dependents arrays when creating FK relationships
 880→   * This is required for ERD diagram generation
 881→   */
 882→  private updateTableDependencies(
 883→    state: DatabaseDocumentation,
 884→    sourceSchemaName: string,
 885→    sourceTableName: string,
 886→    targetSchemaName: string,
 887→    targetTableName: string,
 888→    sourceColumnName: string,
 889→    targetColumnName: string
 890→  ): void {
 891→    // Find source table and add to its dependsOn array
 892→    const sourceSchema = state.schemas.find(s => s.name === sourceSchemaName);
 893→    if (sourceSchema) {
 894→      const sourceTable = sourceSchema.tables.find(t => t.name === sourceTableName);
 895→      if (sourceTable) {
 896→        // Check if this dependency already exists
 897→        const existingDep = sourceTable.dependsOn.find(
 898→          dep => dep.schema === targetSchemaName &&
 899→                 dep.table === targetTableName &&
 900→                 dep.column === sourceColumnName
 901→        );
 902→
 903→        if (!existingDep) {
 904→          sourceTable.dependsOn.push({
 905→            schema: targetSchemaName,
 906→            table: targetTableName,
 907→            column: sourceColumnName,
 908→            referencedColumn: targetColumnName
 909→          });
 910→          console.log(`[AnalysisEngine] Updated dependsOn for ${sourceSchemaName}.${sourceTableName} -> ${targetSchemaName}.${targetTableName}`);
 911→        }
 912→      }
 913→    }
 914→
 915→    // Find target table and add to its dependents array
 916→    const targetSchema = state.schemas.find(s => s.name === targetSchemaName);
 917→    if (targetSchema) {
 918→      const targetTable = targetSchema.tables.find(t => t.name === targetTableName);
 919→      if (targetTable) {
 920→        // Check if this dependent already exists
 921→        const existingDep = targetTable.dependents.find(
 922→          dep => dep.schema === sourceSchemaName &&
 923→                 dep.table === sourceTableName &&
 924→                 dep.column === sourceColumnName
 925→        );
 926→
 927→        if (!existingDep) {
 928→          targetTable.dependents.push({
 929→            schema: sourceSchemaName,
 930→            table: sourceTableName,
 931→            column: sourceColumnName,
 932→            referencedColumn: targetColumnName
 933→          });
 934→          console.log(`[AnalysisEngine] Updated dependents for ${targetSchemaName}.${targetTableName} <- ${sourceSchemaName}.${sourceTableName}`);
 935→        }
 936→      }
 937→    }
 938→  }
