 940→  /**
 941→   * Resolve target table from LLM hint (e.g., "product", "warehouse", "supplier")
 942→   * Returns the best matching table and its likely PK column
 943→   */
 944→  private resolveTargetTable(
 945→    state: DatabaseDocumentation,
 946→    tableHint: string,
 947→    currentSchema: string
 948→  ): { schema: string; table: string; column: string } | null {
 949→    const hint = tableHint.toLowerCase().trim();
 950→
 951→    // Search all schemas for matching table names
 952→    for (const schema of state.schemas) {
 953→      for (const table of schema.tables) {
 954→        const tableLower = table.name.toLowerCase();
 955→
 956→        // Direct match
 957→        if (tableLower === hint || tableLower === hint + 's' || tableLower + 's' === hint) {
 958→          // Find PK column (prefer columns ending in _id or named id)
 959→          const pkColumn = table.columns.find(c => c.isPrimaryKey);
 960→          if (pkColumn) {
 961→            return {
 962→              schema: schema.name,
 963→              table: table.name,
 964→              column: pkColumn.name
 965→            };
 966→          }
 967→
 968→          // Fallback: look for column ending in _id or just 'id'
 969→          const idColumn = table.columns.find(c =>
 970→            c.name.toLowerCase() === 'id' ||
 971→            c.name.toLowerCase() ===  `${tableLower}_id` ||
 972→            c.name.toLowerCase().endsWith('_id')
 973→          );
 974→
 975→          if (idColumn) {
 976→            return {
 977→              schema: schema.name,
 978→              table: table.name,
 979→              column: idColumn.name
 980→            };
 981→          }
 982→
 983→          // Fallback: first column
 984→          if (table.columns.length > 0) {
 985→            return {
 986→              schema: schema.name,
 987→              table: table.name,
 988→              column: table.columns[0].name
 989→            };
 990→          }
 991→        }
 992→
 993→        // Partial match (e.g., "product" matches "prd", "products")
 994→        if (tableLower.includes(hint) || hint.includes(tableLower)) {
 995→          const pkColumn = table.columns.find(c => c.isPrimaryKey);
 996→          if (pkColumn) {
 997→            return {
 998→              schema: schema.name,
 999→              table: table.name,
1000→              column: pkColumn.name
1001→            };
1002→          }
1003→        }
1004→      }
1005→    }
1006→
1007→    return null;
1008→  }
1009→}
