 41→export class AnalysisOrchestrator {
 42→  private config: DBAutoDocConfig;
 43→  private resumeFromState?: string;
 44→  private onProgress: (message: string, data?: any) => void;
 45→
 46→  constructor(options: AnalysisOptions) {
 47→    this.config = options.config;
 48→    this.resumeFromState = options.resumeFromState;
 49→    this.onProgress = options.onProgress || (() => {});
 50→  }
 51→
 52→  /**
 53→   * Execute the full analysis workflow
 54→   */
 55→  public async execute(): Promise<OrchestratorResult> {
 56→    try {
 57→      // Create run folder
 58→      if (!this.config.output.outputDir) {
 59→        throw new Error('output.outputDir must be specified in config');
 60→      }
 61→      const runFolder = await this.createRunFolder(this.config.output.outputDir);
 62→      const stateFilePath = path.join(runFolder, 'state.json');
 63→
 64→      this.onProgress('Created run folder', { path: runFolder });
 65→
 66→      // Initialize state manager
 67→      const stateManager = new StateManager(stateFilePath);
 68→      let state: DatabaseDocumentation;
 69→
 70→      // Load state (either resume or create new)
 71→      if (this.resumeFromState) {
 72→        this.onProgress('Resuming from existing state', { path: this.resumeFromState });
 73→        state = await this.loadAndMergeState(this.resumeFromState, stateManager);
 74→      } else {
 75→        state = await stateManager.load() || stateManager.createInitialState(
 76→          this.config.database.database,
 77→          this.config.database.server
 78→        );
 79→      }
 80→
 81→      // Connect to database
 82→      this.onProgress('Connecting to database');
 83→      const driverConfig: AutoDocConnectionConfig = {
 84→        provider: (this.config.database.provider as 'sqlserver' | 'mysql' | 'postgresql' | 'oracle') || 'sqlserver',
 85→        host: this.config.database.server,
 86→        port: this.config.database.port,
 87→        database: this.config.database.database,
 88→        user: this.config.database.user,
 89→        password: this.config.database.password,
 90→        encrypt: this.config.database.encrypt,
 91→        trustServerCertificate: this.config.database.trustServerCertificate,
 92→        connectionTimeout: this.config.database.connectionTimeout,
 93→        requestTimeout: this.config.database.requestTimeout,
 94→        maxConnections: this.config.database.maxConnections,
 95→        minConnections: this.config.database.minConnections,
 96→        idleTimeoutMillis: this.config.database.idleTimeoutMillis
 97→      };
 98→
 99→      const db = new DatabaseConnection(driverConfig);
100→      await db.connect();
101→      const testResult = await db.test();
102→
103→      if (!testResult.success) {
104→        throw new Error(`Database connection failed: ${testResult.message}`);
105→      }
106→      this.onProgress('Connected to database', { database: this.config.database.database });
107→
108→      // Introspect database (unless resuming with existing schema data)
109→      if (!this.resumeFromState || state.schemas.length === 0) {
110→        this.onProgress('Introspecting database schema');
111→        const driver = db.getDriver();
112→        const introspector = new Introspector(driver);
113→        const schemas = await introspector.getSchemas(this.config.schemas, this.config.tables);
114→        state.schemas = schemas;
115→        this.onProgress('Schema introspection complete', {
116→          schemas: schemas.length,
117→          tables: schemas.reduce((sum, s) => sum + s.tables.length, 0)
118→        });
119→
120→        // Analyze data
121→        this.onProgress('Analyzing table data');
122→        const sampler = new DataSampler(driver, this.config.analysis);
123→        let samplingErrors = 0;
124→        for (const schema of schemas) {
125→          for (const table of schema.tables) {
126→            try {
127→              await sampler.analyzeTable(schema.name, table.name, table.columns);
128→            } catch (error) {
129→              samplingErrors++;
130→              const errorMsg = `Warning: Failed to analyze data for ${schema.name}.${table.name}: ${(error as Error).message}`;
131→              console.error(errorMsg);
132→              this.onProgress(errorMsg, { schema: schema.name, table: table.name, error: (error as Error).message });
133→              // Continue with next table - partial data better than no data
134→            }
135→          }
136→        }
137→        this.onProgress('Data analysis complete', {
138→          tablesAnalyzed: schemas.reduce((sum, s) => sum + s.tables.length, 0) - samplingErrors,
139→          errors: samplingErrors
140→        });
141→
142→        // Relationship Discovery Phase (if enabled)
143→        if (this.config.analysis.relationshipDiscovery?.enabled) {
144→          this.onProgress('Checking if relationship discovery should run');
145→
146→          const triggerAnalysis = DiscoveryTriggerAnalyzer.analyzeSchemas(state.schemas);
147→
148→          if (triggerAnalysis.shouldRun) {
149→            this.onProgress('Relationship discovery triggered', {
150→              reason: triggerAnalysis.reason,
151→              tablesWithoutPK: triggerAnalysis.details.tablesWithoutPK,
152→              actualFKs: triggerAnalysis.details.totalFKs,
153→              expectedMinFKs: triggerAnalysis.details.expectedMinFKs
154→            });
155→
156→            const discoveryEngine = new DiscoveryEngine({
157→              driver,
158→              config: this.config.analysis.relationshipDiscovery,
159→              aiConfig: this.config.ai,
160→              schemas: state.schemas,
161→              onProgress: this.onProgress
162→            });
163→
164→            // Calculate token budget for discovery
165→            const totalTokenBudget = this.config.analysis.guardrails?.maxTokensPerRun;
166→            const discoveryRatio = this.config.analysis.relationshipDiscovery.tokenBudget?.ratioOfTotal || 0.25;
167→            const discoveryTokenBudget = totalTokenBudget
168→              ? Math.floor(totalTokenBudget * discoveryRatio)
169→              : this.config.analysis.relationshipDiscovery.tokenBudget?.maxTokens || 50000;
170→
171→            const discoveryResult = await discoveryEngine.discover(discoveryTokenBudget, triggerAnalysis);
172→
173→            // Save to new phases structure
174→            state.phases.keyDetection = discoveryResult.phase;
175→
176→            // Apply discovered relationships to schema
177→            discoveryEngine.applyDiscoveriesToState(state, discoveryResult.phase);
178→
179→            // Merge column statistics into schema columns
180→            discoveryResult.statsCache.mergeIntoSchemas(state.schemas);
181→
182→            this.onProgress('Relationship discovery complete', {
183→              primaryKeysDiscovered: discoveryResult.phase.discovered.primaryKeys.length,
184→              foreignKeysDiscovered: discoveryResult.phase.discovered.foreignKeys.length,
185→              tokensUsed: discoveryResult.phase.tokenBudget.used,
186→              guardrailsReached: discoveryResult.guardrailsReached,
187→              totalSchemas: state.schemas.length
188→            });
189→
190→            // Save state with discovery results and stats cache
191→            await stateManager.save(state);
192→          } else {
193→            this.onProgress('Relationship discovery skipped', {
194→              reason: triggerAnalysis.reason
195→            });
196→          }
197→        }
198→      }
199→
200→      // Topological sort

 1→/**
 2→ * Custom Nunjucks loader for file-based prompts
 3→ * Pattern adapted from Templates package's TemplateEntityLoader
 4→ */
 5→
 6→import nunjucks from 'nunjucks';
 7→import * as fs from 'fs/promises';
 8→import * as path from 'path';
 9→
10→export class PromptFileLoader extends nunjucks.Loader {
11→  public async: true = true;
12→
13→  private prompts: Map<string, string> = new Map();
14→
15→  constructor(private promptsDir: string) {
16→    super();
17→  }
18→
19→  /**
20→   * Load all prompt files from directory
21→   */
22→  public async loadAll(): Promise<void> {
23→    const files = await fs.readdir(this.promptsDir);
24→
25→    for (const file of files) {
26→      if (file.endsWith('.md') || file.endsWith('.txt')) {
27→        const promptName = path.basename(file, path.extname(file));
28→        const filePath = path.join(this.promptsDir, file);
29→        const content = await fs.readFile(filePath, 'utf-8');
30→        this.prompts.set(promptName, content);
31→      }
32→    }
33→  }
34→
35→  /**
36→   * Required by Nunjucks Loader - provides template source
37→   * Pattern from Templates package
38→   */
39→  public getSource(name: string, callback: any): void {
40→    const content = this.prompts.get(name);
41→    if (content) {
42→      callback(null, {
43→        src: content,
44→        path: name,
45→        noCache: true
46→      });
47→    } else {
48→      callback(new Error(`Prompt not found: ${name}`));
49→    }
50→  }
51→}
