  1→/**
  2→ * LLM Sanity Checker
  3→ * Uses LLM intelligence to review and reject obviously wrong PK/FK candidates
  4→ * This is a MACRO-LEVEL review that happens once after statistical detection
  5→ */
  6→
  7→import { BaseLLM, ChatParams, ChatResult } from '@memberjunction/ai';
  8→import { PKCandidate, FKCandidate } from '../types/discovery.js';
  9→import { AIConfig } from '../types/config.js';
 10→import { createLLMInstance } from '../utils/llm-factory.js';
 11→
 12→export interface SanityCheckResult {
 13→  invalidPKs: Array<{
 14→    schema: string;
 15→    table: string;
 16→    column: string;
 17→    reason: string;
 18→  }>;
 19→  invalidFKs: Array<{
 20→    schema: string;
 21→    table: string;
 22→    column: string;
 23→   reason: string;
 24→  }>;
 25→  suggestions: string[];
 26→  tokensUsed: number;
 27→}
 28→
 29→export class LLMSanityChecker {
 30→  private llm: BaseLLM;
 31→
 32→  constructor(private aiConfig: AIConfig) {
 33→    // Create LLM instance using shared factory (DRY principle)
 34→    this.llm = createLLMInstance(aiConfig.provider, aiConfig.apiKey);
 35→  }
 36→
 37→  /**
 38→   * Review all detected PKs and FKs for obvious errors
 39→   * This is a one-time macro review after statistical detection
 40→   */
 41→  public async reviewCandidates(
 42→    pkCandidates: PKCandidate[],
 43→    fkCandidates: FKCandidate[]
 44→  ): Promise<SanityCheckResult> {
 45→    console.log(`[LLMSanityChecker] Reviewing ${pkCandidates.length} PK candidates and ${fkCandidates.length} FK candidates`);
 46→
 47→    // Build prompt with all candidates
 48→    const prompt = this.buildSanityCheckPrompt(pkCandidates, fkCandidates);
 49→
 50→    // Call LLM
 51→    const params: ChatParams = {
 52→      model: this.aiConfig.model,
 53→      messages: [
 54→        {
 55→          role: 'system',
 56→          content: 'You are a database schema expert specializing in identifying incorrect primary key and foreign key  candidates. Your job is to reject obviously wrong candidates based on naming patterns and data types.'
 57→        },
 58→        {
 59→          role: 'user',
 60→          content: prompt
 61→        }
 62→      ],
 63→      temperature: 0.1,
 64→      maxOutputTokens: this.aiConfig.maxTokens,
 65→      responseFormat: 'JSON'
 66→    };
 67→
 68→    console.log(`[LLMSanityChecker] Calling LLM for sanity check...`);
 69→    const chatResult: ChatResult = await this.llm.ChatCompletion(params);
 70→
 71→    if (!chatResult.success) {
 72→      console.warn(`[LLMSanityChecker] LLM call failed: ${chatResult.errorMessage}`);
 73→      return {
 74→        invalidPKs: [],
 75→        invalidFKs: [],
 76→        suggestions: [],
 77→        tokensUsed: 0
 78→      };
 79→    }
 80→
 81→    // Parse LLM response
 82→    const content = chatResult.data.choices[0].message.content;
 83→    const usage = chatResult.data.usage;
 84→
 85→    try {
 86→      const result = JSON.parse(content) as {
 87→        invalidPKs: Array<{ schema: string; table: string; column: string; reason: string }>;
 88→        invalidFKs: Array<{ schema: string; table: string; column: string; reason: string }>;
 89→        suggestions: string[];
 90→      };
 91→
 92→      console.log(`[LLMSanityChecker] Found ${result.invalidPKs.length} invalid PKs, ${result.invalidFKs.length} invalid FKs`);
 93→
 94→      return {
 95→        invalidPKs: result.invalidPKs,
 96→        invalidFKs: result.invalidFKs,
 97→        suggestions: result.suggestions || [],
 98→        tokensUsed: usage?.totalTokens || 0
 99→      };
100→    } catch (parseError) {
101→      console.error(`[LLMSanityChecker] Failed to parse LLM response: ${(parseError as Error).message}`);
102→      console.error(`[LLMSanityChecker] Raw content: ${content}`);
103→      return {
104→        invalidPKs: [],
105→        invalidFKs: [],
106→        suggestions: [],
107→        tokensUsed: usage?.totalTokens || 0
108→      };
109→    }
110→  }
111→
112→  /**
113→   * Build the sanity check prompt with all candidate information
114→   */
115→  private buildSanityCheckPrompt(
116→    pkCandidates: PKCandidate[],
117→    fkCandidates: FKCandidate[]
118→  ): string {
119→    // Group PKs by table
120→    const pksByTable = new Map<string, PKCandidate[]>();
121→    for (const pk of pkCandidates) {
122→      const key = `${pk.schemaName}.${pk.tableName}`;
123→      if (!pksByTable.has(key)) {
124→        pksByTable.set(key, []);
