126→      pksByTable.get(key)!.push(pk);
127→    }
128→
129→    // Group FKs by table
130→    const fksByTable = new Map<string, FKCandidate[]>();
131→    for (const fk of fkCandidates) {
132→      const key = `${fk.schemaName}.${fk.sourceTable}`;
133→      if (!fksByTable.has(key)) {
134→        fksByTable.set(key, []);
135→      }
136→      fksByTable.get(key)!.push(fk);
137→    }
138→
139→    let prompt = `You are reviewing database primary key and foreign key candidates for obvious errors.
140→
141→CRITICAL RULES:
142→1. Date/time fields are NEVER primary keys (they are not unique per row)
143→2. Quantity, count, amount fields are NEVER primary keys
144→3. Text fields (names, descriptions, notes) are NEVER primary keys
145→4. Boolean/flag fields are NEVER primary keys
146→5. Each table should have exactly 1 PK (or a composite PK with 2-3 columns max)
147→6. Foreign keys should reference another table, not point to themselves
148→
149→DETECTED PRIMARY KEY CANDIDATES:
150→

