  1→/**
  2→ * Handles backpropagation of insights from child tables to parent tables
  3→ */
  4→
  5→import { DatabaseDocumentation, TableDefinition, AnalysisRun } from '../types/state.js';
  6→import { BackpropagationTrigger } from '../types/analysis.js';
  7→import { BackpropagationPromptResult } from '../types/prompts.js';
  8→import { PromptEngine } from '../prompts/PromptEngine.js';
  9→import { StateManager } from '../state/StateManager.js';
 10→import { IterationTracker } from '../state/IterationTracker.js';
 11→
 12→export class BackpropagationEngine {
 13→  constructor(
 14→    private promptEngine: PromptEngine,
 15→    private stateManager: StateManager,
 16→    private iterationTracker: IterationTracker,
 17→    private maxDepth: number
 18→  ) {}
 19→
 20→  /**
 21→   * Execute backpropagation for a set of triggers
 22→   */
 23→  public async execute(
 24→    state: DatabaseDocumentation,
 25→    run: AnalysisRun,
 26→    triggers: BackpropagationTrigger[]
 27→  ): Promise<{ tablesUpdated: number; tokensUsed: number }> {
 28→    let tablesUpdated = 0;
 29→    let totalTokensUsed = 0;
 30→
 31→    // Group triggers by target table
 32→    const triggersByTable = this.groupTriggersByTable(triggers);
 33→
 34→    for (const [tableKey, tableTriggers] of triggersByTable) {
 35→      const [schemaName, tableName] = tableKey.split('.');
 36→      const table = this.stateManager.findTable(state, schemaName, tableName);
 37→
 38→      if (!table) {
 39→        this.iterationTracker.addWarning(
 40→          run,
 41→          `Backpropagation target table not found: ${tableKey}`
 42→        );
 43→        continue;
 44→      }
 45→
 46→      // Skip if no current description
 47→      if (!table.description) {
 48→        continue;
 49→      }
 50→
 51→      // Get current description details
 52→      const latestIteration = table.descriptionIterations[table.descriptionIterations.length - 1];
 53→
 54→      // Combine insights from all triggers for this table
 55→      const insights = tableTriggers.map(t => t.insight).join('\n\n');
 56→
 57→      // Execute backpropagation prompt
 58→      const result = await this.promptEngine.executePrompt<BackpropagationPromptResult>(
 59→        'backpropagation',
 60→        {
 61→          schemaName,
 62→          tableName,
 63→          currentDescription: table.description,
 64→          currentReasoning: latestIteration?.reasoning || '',
 65→          currentConfidence: latestIteration?.confidence || 0,
 66→          insights
 67→        },
 68→        {
 69→          responseFormat: 'JSON'
 70→        }
 71→      );
 72→
 73→      if (!result.success || !result.result) {
 74→        this.iterationTracker.addError(run, `Backpropagation failed for ${tableKey}: ${result.errorMessage}`);
 75→        continue;
 76→      }
 77→
 78→      totalTokensUsed += result.tokensUsed;
 79→      this.iterationTracker.addTokenUsage(run, result.tokensUsed, result.cost);
 80→
 81→      // Check if revision is needed
 82→      if (result.result.needsRevision) {
 83→        // Update table description
 84→        this.stateManager.updateTableDescription(
 85→          table,
 86→          result.result.revisedDescription || result.result.reasoning,
 87→          result.result.reasoning,
 88→          result.result.confidence,
 89→          run.modelUsed,
 90→          'backpropagation'
 91→        );
 92→
 93→        tablesUpdated++;
 94→
 95→        this.iterationTracker.addLogEntry(run, {
 96→          level: table.dependencyLevel || 0,
 97→          schema: schemaName,
 98→          table: tableName,
 99→          action: 'backpropagate',
100→          result: 'changed',
101→          message: 'Description revised based on child table insights',
102→          tokensUsed: result.tokensUsed
103→        });
104→      } else {
105→        this.iterationTracker.addLogEntry(run, {
106→          level: table.dependencyLevel || 0,
107→          schema: schemaName,
108→          table: tableName,
109→          action: 'backpropagate',
110→          result: 'unchanged',
111→          message: 'No revision needed',
112→          tokensUsed: result.tokensUsed
113→        });
114→      }
115→    }
116→
117→    if (tablesUpdated > 0) {
118→      this.iterationTracker.incrementBackpropagation(run);
119→    }
120→
121→    return { tablesUpdated, tokensUsed: totalTokensUsed };
122→  }
123→
124→  /**
125→   * Detect insights about parent tables from analysis result
126→   * Uses LLM-provided insights instead of NLP pattern matching
127→   */
128→  public detectParentInsights(
129→    table: TableDefinition,
130→    analysisResult: any,
131→    schema?: string,
132→    tableName?: string
133→  ): BackpropagationTrigger[] {
134→    const triggers: BackpropagationTrigger[] = [];
135→
136→    // Current table full name for source
137→    const sourceTable = schema && tableName ? `${schema}.${tableName}` : 'unknown';
138→
139→    // Use LLM-provided parent table insights (much more accurate than NLP)
140→    const parentInsights = analysisResult.parentTableInsights || [];
141→
142→    for (const insight of parentInsights) {
143→      triggers.push({
144→        sourceTable,
145→        targetTable: insight.parentTable,
146→        insight: insight.insight,
147→        confidence: insight.confidence
148→      });
149→    }
150→
151→    return triggers;
152→  }
153→
154→  /**
155→   * Group triggers by target table
156→   */
157→  private groupTriggersByTable(
158→    triggers: BackpropagationTrigger[]
159→  ): Map<string, BackpropagationTrigger[]> {
160→    const grouped = new Map<string, BackpropagationTrigger[]>();
161→
162→    for (const trigger of triggers) {
163→      if (!grouped.has(trigger.targetTable)) {
164→        grouped.set(trigger.targetTable, []);
165→      }
166→      grouped.get(trigger.targetTable)!.push(trigger);
167→    }
168→
169→    return grouped;
170→  }
171→}
