const PROVIDER_TO_DRIVER_CLASS: Record<string, string> = {
  'gemini': 'GeminiLLM',
  'openai': 'OpenAILLM',
  'anthropic': 'AnthropicLLM',
  'groq': 'GroqLLM',
  'mistral': 'MistralLLM',
  'vertex': 'VertexLLM',
  'azure': 'AzureLLM',
  'cerebras': 'CerebrasLLM',
  'openrouter': 'OpenRouterLLM',
  'xai': 'xAILLM',
  'bedrock': 'BedrockLLM'
};

export function createLLMInstance(provider: string, apiKey: string): BaseLLM {
  const driverClass = PROVIDER_TO_DRIVER_CLASS[provider.toLowerCase()];
  const llm = MJGlobal.Instance.ClassFactory.CreateInstance<BaseLLM>(BaseLLM, driverClass, apiKey);
  if (!llm) throw new Error(`Failed to create LLM instance for provider: ${provider}`);
  return llm;
}
```

For Memento (Python), use **litellm** instead for unified provider interface.

